// ============================================================
// ANA-06 — Monta a mensagem de confirmação da véspera.
// Determinística de propósito: o texto que SAI é previsível e
// auditável (CFM 2.336/2023). A RESPOSTA do paciente volta para a
// Ana do ANA-01, que conduz confirmação, remarcação ou cancelamento.
// ============================================================
const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira',
              'quinta-feira', 'sexta-feira', 'sábado'];

// siglas que sempre vão em caixa alta
const SIGLAS = ['usg', 'rx', 'tc', 'ecg', 'eeg', 'mapa', 'dna', 'psa', 'tsh', 'holter'];

// grafias sem acento que a recepção digita → forma correta para o paciente
const ACENTOS = {
  'abdomen': 'abdômen', 'abdominal': 'abdominal', 'torax': 'tórax',
  'prostata': 'próstata', 'obstetrico': 'obstétrico', 'obstetrica': 'obstétrica',
  'maos': 'mãos', 'articulacao': 'articulação', 'coracao': 'coração',
  'tireoide': 'tireoide', 'cervical': 'cervical', 'toxicologico': 'toxicológico', 'toxico': 'toxicológico',
  'bacterioscopico': 'bacterioscópico', 'secrecao': 'secreção',
  'espiro': 'espirometria', 'tv': 'transvaginal', 'morfologico': 'morfológico'
};

function primeiroNome(nome) {
  const n = String(nome || '').trim().split(/\s+/)[0] || '';
  if (n.length < 2 || !/^[A-Za-zÀ-ÿ]+$/.test(n)) return '';
  return n.charAt(0).toUpperCase() + n.slice(1).toLowerCase();
}

// palavras internas que não devem chegar ao paciente
const INTERNOS = /\b(solumed|poiares|particular|convenio|conv[êe]nio|encaixe|retorno)\b/gi;
// âncoras usadas quando o título não segue o padrão "hora - nome - exame"
const ANCORA = /\b(usg|ultrassom|ultrassonografia|rx|raio[- ]?x|tc|tomografia|ecg|eletro\w*|eeg|holter|mapa|coleta|espiro\w*|toxicol\w*|papanicolau|sexagem|romberg|doppler|check[- ]?up|bacterioscopico|bacterioscópico)\b/i;

function nomeExame(evento) {
  const bruto = String(evento || '').trim();
  if (!bruto) return 'exame';
  // o exame é o último trecho do título: "09:00 - Maria Silva - USG ABDÔMEN"
  const partes = bruto.split(/\s*[-–]\s*/).map(p => p.trim()).filter(Boolean);
  let ex = partes.length > 1 ? partes[partes.length - 1] : bruto;
  // título fora do padrão (sem hífen): corta a partir do nome do exame
  if (partes.length === 1) {
    const m = ex.match(ANCORA);
    ex = m ? ex.slice(m.index) : '';
  }
  ex = ex.replace(/^\d{1,2}\s*[hH:]\s*\d{0,2}\s*/, '').replace(/[()]/g, ' ')
         .replace(INTERNOS, ' ').replace(/[.\s]+$/, '')
         .replace(/\s+/g, ' ').trim();
  if (ex.length < 3) return 'exame';
  ex = ex.toLowerCase().split(' ').map(function (p) {
    const limpa = p.replace(/[^a-zà-ÿ]/g, '');
    if (ACENTOS[limpa]) return p.replace(limpa, ACENTOS[limpa]);
    return p;
  }).join(' ');
  ex = ex.split(' ').map(p => SIGLAS.indexOf(p) >= 0 ? p.toUpperCase() : p).join(' ');
  return ex;
}

const j = $input.first().json;
const nome = primeiroNome(j.nome);
const saudacao = nome ? ('Oi, ' + nome + '!') : 'Oi!';
const exame = nomeExame(j.evento);

const partesData = String(j.data).split('-').map(Number);
const alvo = Date.UTC(partesData[0], partesData[1] - 1, partesData[2]);
const dataBr = String(partesData[2]).padStart(2, '0') + '/' + String(partesData[1]).padStart(2, '0');

// "hoje" em São Paulo: o Brasil não tem mais horário de verão, então UTC-3 é fixo
const agoraSP = new Date(Date.now() - 3 * 60 * 60 * 1000);
const hoje = Date.UTC(agoraSP.getUTCFullYear(), agoraSP.getUTCMonth(), agoraSP.getUTCDate());
// na sexta-feira a rotina cobre a segunda: aí não é "amanhã"
const quando = (alvo - hoje) === 86400000
  ? 'de amanhã'
  : ('de ' + DIAS[new Date(alvo).getUTCDay()]);

let horario = '';
if (/^\d{2}:\d{2}$/.test(j.hora || '')) horario = ', às *' + j.hora + '*';
else if (String(j.turno || '').indexOf('manh') === 0) horario = ', de *manhã*';
else if (j.turno) horario = ', à *tarde*';

const detalhe = '*' + exame + '*, dia *' + dataBr + '*' + horario;

// 3 variações estáveis: o mesmo paciente recebe sempre o mesmo estilo
const v = Number(String(j.phone).slice(-3)) % 3;
let texto;
if (v === 0) {
  texto = saudacao + ' 😊 Aqui é a Ana, da Total Quality.\n\n'
        + 'Passando pra confirmar seu exame ' + quando + ': ' + detalhe + '.\n\n'
        + 'Posso confirmar sua presença? Se precisar remarcar, é só me falar que eu ajeito pra você 🙂';
} else if (v === 1) {
  texto = saudacao + ' Tudo bem? É a Ana, da Total Quality 😊\n\n'
        + 'Seu exame ' + quando + ' está marcado: ' + detalhe + '.\n\n'
        + 'Tá tudo certo pra você vir? Se precisar mudar a data, me avisa que a gente remarca sem problema.';
} else {
  texto = saudacao + ' Ana aqui, da Total Quality 🙂\n\n'
        + 'Passando só pra lembrar do seu exame ' + quando + ': ' + detalhe + '.\n\n'
        + 'Consigo confirmar sua presença?';
}

texto += '\n\nA gente fica na *Av. Anchieta, 1010* — Centro. Chega uns 15 minutinhos antes, tá? '
       + 'E se quiser as orientações de preparo, é só me pedir.';

return [{ json: { phone: j.phone, nome: j.nome, data: j.data, hora: j.hora,
                  exame: exame, texto: texto } }];
